/**
 * assets/nota-textura-embutida.js
 * -------------------------------------------------
 * As MESMAS texturas de assets/pictures/, so que embutidas em
 * base64 dentro deste arquivo. Existe por um motivo único: quando a
 * página e aberta direto do disco (protocolo file://, sem servidor),
 * o navegador se recusa a mandar uma imagem carregada de arquivo para
 * a placa de vídeo (a textura sai "contaminada" por segurança) e o
 * papel apareceria branco.
 *
 * models/paper-note-factory.js procura por este objeto sozinho e so o
 * usa quando precisa (file:// ou PNG faltando). Num servidor de
 * verdade - Acode, Live Server, itch.io, hospedagem qualquer - os PNGs
 * normais são usados e este arquivo pode até ser apagado do projeto.
 * -------------------------------------------------
 */
window.PaperNoteTexturasEmbutidas = {
  frente: "data:image/png;base64,",
  verso: "data:image/png;base64,",
  frente256: "data:image/png;base64,",
  verso256: "data:image/png;base64,"
};
